export function knownDelegate(chainId: number | undefined, address?: string): string | undefined {
  const k = address ? KNOWN.get(address.toLowerCase()) : undefined;
  if (!k) return undefined;
  return k.chains === 'all' || (chainId !== undefined && k.chains.includes(chainId)) ? k.name : undefined;
}
